INSERT OR IGNORE INTO mission_study_materials (mission_id,title,introduction,explanation,example_code,example_explanation,key_points_json,common_mistakes_json,references_json) VALUES
(139,'Seletores de tipo','Antes da batalha, entenda seletores fundamentais.','seletores fundamentais integra esta etapa do aprendizado de CSS.','body { color: #e2e8f0; background-color: #020617; }','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda seletores fundamentais","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — CSS","url":"https://developer.mozilla.org/en-US/docs/Web/CSS"}]'),
(140,'Seletores de classe','Antes da batalha, entenda classes reutilizáveis.','classes reutilizáveis integra esta etapa do aprendizado de CSS.','.card { padding: 16px; border-radius: 12px; }','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda classes reutilizáveis","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — CSS","url":"https://developer.mozilla.org/en-US/docs/Web/CSS"}]'),
(141,'Herança','Antes da batalha, entenda propriedades herdáveis.','propriedades herdáveis integra esta etapa do aprendizado de CSS.','.page { color: #e2e8f0; font-family: system-ui; }','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda propriedades herdáveis","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — CSS","url":"https://developer.mozilla.org/en-US/docs/Web/CSS"}]'),
(142,'Fundamentos visuais','Antes da batalha, entenda seletores, contraste e espaço.','seletores, contraste e espaço integra esta etapa do aprendizado de CSS.','.card { color: #e2e8f0; background-color: #111827; padding: 24px; border-radius: 12px; }','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda seletores, contraste e espaço","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — CSS","url":"https://developer.mozilla.org/en-US/docs/Web/CSS"}]'),
(143,'Centralização','Antes da batalha, entenda margin inline auto.','margin inline auto integra esta etapa do aprendizado de CSS.','.container { width: 90%; margin: 0 auto; }','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda margin inline auto","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — CSS","url":"https://developer.mozilla.org/en-US/docs/Web/CSS"}]'),
(144,'Imagens fluidas','Antes da batalha, entenda max-width e height.','max-width e height integra esta etapa do aprendizado de CSS.','img { max-width: 100%; height: auto; }','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda max-width e height","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — CSS","url":"https://developer.mozilla.org/en-US/docs/Web/CSS"}]'),
(145,'Caixa profissional','Antes da batalha, entenda dimensionamento integrado.','dimensionamento integrado integra esta etapa do aprendizado de CSS.','.painel { width: 90%; max-width: 960px; padding: 24px; overflow: auto; }','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda dimensionamento integrado","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — CSS","url":"https://developer.mozilla.org/en-US/docs/Web/CSS"}]'),
(146,'Pseudo-elementos','Antes da batalha, entenda conteúdo decorativo.','conteúdo decorativo integra esta etapa do aprendizado de CSS.','.badge::before { content: "✦"; color: #22d3ee; }','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda conteúdo decorativo","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — CSS","url":"https://developer.mozilla.org/en-US/docs/Web/CSS"}]'),
(147,'Fundos dimensionados','Antes da batalha, entenda background-size e position.','background-size e position integra esta etapa do aprendizado de CSS.','.hero { background-size: cover; background-position: center; }','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda background-size e position","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — CSS","url":"https://developer.mozilla.org/en-US/docs/Web/CSS"}]'),
(148,'Componente interativo','Antes da batalha, entenda estados e feedback.','estados e feedback integra esta etapa do aprendizado de CSS.','.button { cursor: pointer; transition: transform .2s ease; border-radius: 8px; }','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda estados e feedback","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — CSS","url":"https://developer.mozilla.org/en-US/docs/Web/CSS"}]'),
(149,'Fluxo em coluna','Antes da batalha, entenda flex-direction.','flex-direction integra esta etapa do aprendizado de CSS.','.sidebar { display: flex; flex-direction: column; gap: 12px; }','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda flex-direction","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — CSS","url":"https://developer.mozilla.org/en-US/docs/Web/CSS"}]'),
(150,'Ordem flexível','Antes da batalha, entenda order.','order integra esta etapa do aprendizado de CSS.','.featured { order: -1; }','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda order","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — CSS","url":"https://developer.mozilla.org/en-US/docs/Web/CSS"}]'),
(151,'Layout de aplicação','Antes da batalha, entenda Grid e Flex combinados.','Grid e Flex combinados integra esta etapa do aprendizado de CSS.','.layout { display: grid; grid-template-columns: 240px 1fr; gap: 24px; }','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda Grid e Flex combinados","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — CSS","url":"https://developer.mozilla.org/en-US/docs/Web/CSS"}]'),
(152,'Rolagem suave','Antes da batalha, entenda scroll-behavior.','scroll-behavior integra esta etapa do aprendizado de CSS.','html { scroll-behavior: smooth; }','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda scroll-behavior","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — CSS","url":"https://developer.mozilla.org/en-US/docs/Web/CSS"}]'),
(153,'Mídia recortada','Antes da batalha, entenda object-fit.','object-fit integra esta etapa do aprendizado de CSS.','.preview { aspect-ratio: 16/9; object-fit: cover; }','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda object-fit","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — CSS","url":"https://developer.mozilla.org/en-US/docs/Web/CSS"}]'),
(154,'Movimento controlado','Antes da batalha, entenda transform e transition.','transform e transition integra esta etapa do aprendizado de CSS.','.badge { transition: transform .2s ease; transform: translateY(-4px) scale(1.05); }','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda transform e transition","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — CSS","url":"https://developer.mozilla.org/en-US/docs/Web/CSS"}]'),
(155,'Esquema de cores','Antes da batalha, entenda color-scheme.','color-scheme integra esta etapa do aprendizado de CSS.',':root { color-scheme: dark; --accent: #22d3ee; }','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda color-scheme","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — CSS","url":"https://developer.mozilla.org/en-US/docs/Web/CSS"}]'),
(156,'Sistema visual final','Antes da batalha, entenda tokens e componente profissional.','tokens e componente profissional integra esta etapa do aprendizado de CSS.','.card { display: grid; gap: 16px; padding: 24px; color: #e2e8f0; background-color: #0f172a; border-radius: 16px; }','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda tokens e componente profissional","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — CSS","url":"https://developer.mozilla.org/en-US/docs/Web/CSS"}]');
