INSERT OR IGNORE INTO mission_study_materials (mission_id,title,introduction,explanation,example_code,example_explanation,key_points_json,common_mistakes_json,references_json) VALUES
(157,'Operações básicas','Antes da batalha, entenda operadores aritméticos.','Operadores transformam valores e objetos agrupam resultados relacionados.','return { soma: a + b, produto: a * b };','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda operadores aritméticos","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — JavaScript","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript"}]'),
(158,'Decisões completas','Antes da batalha, entenda if, else if e else.','Condições ordenadas permitem tratar caminhos mutuamente exclusivos.','if (n > 0) return ''positivo'';','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda if, else if e else","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — JavaScript","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript"}]'),
(159,'Fundamentos integrados','Antes da batalha, entenda variáveis, repetição e condição.','Percorra uma vez e acumule somente os indicadores necessários.','for (const valor of valores) { soma += valor; if (valor > 0) positivos++; }','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda variáveis, repetição e condição","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — JavaScript","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript"}]'),
(160,'Filtragem','Antes da batalha, entenda Array.filter.','filter cria uma lista somente com itens aprovados pelo predicado.','return itens.filter(item => item.ativo);','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda Array.filter","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — JavaScript","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript"}]'),
(161,'Verificação parcial','Antes da batalha, entenda Array.some.','some encerra quando encontra o primeiro item correspondente.','return valores.some(valor => valor < 0);','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda Array.some","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — JavaScript","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript"}]'),
(162,'Pipeline de coleção','Antes da batalha, entenda filter, map e join.','Encadeie transformações pequenas na ordem em que os dados mudam.','alunos.filter(a => a.nota >= 7).map(a => a.nome.toUpperCase()).join('', '');','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda filter, map e join","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — JavaScript","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript"}]'),
(163,'Índice por identificador','Antes da batalha, entenda objetos como índice.','Um índice evita buscas repetidas quando o acesso é feito por identificador.','for (const item of itens) indice[item.id] = item;','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda objetos como índice","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — JavaScript","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript"}]'),
(164,'Valores de objeto','Antes da batalha, entenda Object.values.','Object.values expõe os valores para filtragem e redução.','Object.values(objeto).filter(v => typeof v === ''number'').reduce((a, b) => a + b, 0);','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda Object.values","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — JavaScript","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript"}]'),
(165,'Catálogo indexado','Antes da batalha, entenda normalização e indexação.','Valide antes de indexar para manter o contrato da estrutura resultante.','if (item.id != null) catalogo[item.id] = item;','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda normalização e indexação","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — JavaScript","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript"}]'),
(166,'Intercalação','Antes da batalha, entenda combinação de arrays.','Use o maior comprimento e adicione somente posições existentes.','for (let i = 0; i < Math.max(a.length, b.length); i++) { if (i < a.length) saida.push(a[i]); }','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda combinação de arrays","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — JavaScript","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript"}]'),
(167,'Maiores valores','Antes da batalha, entenda ordenação e recorte.','Copie, ordene e recorte para preservar a entrada.','return [...valores].sort((a, b) => b - a).slice(0, limite);','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda ordenação e recorte","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — JavaScript","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript"}]'),
(168,'Relatório de ranking','Antes da batalha, entenda ordenação, projeção e posição.','Ordene uma cópia antes de projetar a posição de cada registro.','[...jogadores].sort((a,b) => b.pontos-a.pontos).map((j,i) => ({ posicao:i+1, ...j }));','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda ordenação, projeção e posição","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — JavaScript","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript"}]'),
(169,'JSON seguro','Antes da batalha, entenda try e catch.','Exceções de entrada devem ser convertidas no contrato esperado pela função.','try { return JSON.parse(texto); } catch { return null; }','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda try e catch","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — JavaScript","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript"}]'),
(170,'Parâmetros de URL','Antes da batalha, entenda serialização de dados.','Object.entries e encodeURIComponent produzem uma query previsível.','Object.entries(parametros).map(([k,v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join(''&'');','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda serialização de dados","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — JavaScript","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript"}]'),
(171,'Processamento robusto','Antes da batalha, entenda parse, validação e projeção.','Separe leitura, validação e saída para impedir dados inconsistentes.','const dado = JSON.parse(texto); if (!dado.nome || dado.idade < 18) return null;','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda parse, validação e projeção","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — JavaScript","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript"}]'),
(172,'Diferença de coleções','Antes da batalha, entenda Set para comparação.','Um Set torna a consulta de existência direta e eficiente.','const atuais = new Set(depois.map(x => x.id)); return antes.filter(x => !atuais.has(x.id)).map(x => x.id);','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda Set para comparação","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — JavaScript","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript"}]'),
(173,'Média móvel','Antes da batalha, entenda janela deslizante.','Calcule cada intervalo completo e avance uma posição por vez.','for (let i = 0; i <= valores.length - janela; i++) saida.push(valores.slice(i, i + janela).reduce((a,b)=>a+b,0)/janela);','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda janela deslizante","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — JavaScript","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript"}]'),
(174,'Painel analítico','Antes da batalha, entenda pipeline profissional de dados.','Agregue valores e identidades em uma passagem, mantendo o caso vazio explícito.','const total = eventos.reduce((s,e)=>s+e.valor,0); return { total, usuarios:new Set(eventos.map(e=>e.usuario)).size, media:eventos.length ? total/eventos.length : 0 };','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda pipeline profissional de dados","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"MDN — JavaScript","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript"}]');
--> statement-breakpoint
