INSERT OR IGNORE INTO mission_study_materials (mission_id,title,introduction,explanation,example_code,example_explanation,key_points_json,common_mistakes_json,references_json) VALUES
(175,'Coluna calculada','Antes da batalha, entenda expressões no SELECT.','Expressões calculam novos valores sem alterar os dados armazenados.','SELECT NOME,PRECO,ROUND(PRECO*0.9,2) AS PROMOCIONAL FROM PRODUTOS WHERE ATIVO=1 ORDER BY ID','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda expressões no SELECT","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"SQLite — SQL","url":"https://sqlite.org/lang.html"}]'),
(176,'Catálogo básico','Antes da batalha, entenda seleção, filtro e ordenação.','Combine projeção, alias, filtro e ordenação em uma consulta legível.','SELECT ID,NOME,PRECO AS VALOR FROM PRODUTOS WHERE ATIVO=1 AND PRECO>=80 ORDER BY PRECO,NOME','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda seleção, filtro e ordenação","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"SQLite — SQL","url":"https://sqlite.org/lang.html"}]'),
(177,'Paginação com OFFSET','Antes da batalha, entenda LIMIT e OFFSET.','OFFSET ignora as primeiras linhas após a ordenação definida.','SELECT ID,NOME FROM PRODUTOS ORDER BY ID LIMIT 2 OFFSET 2','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda LIMIT e OFFSET","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"SQLite — SQL","url":"https://sqlite.org/lang.html"}]'),
(178,'Filtro profissional','Antes da batalha, entenda condições, nulos e paginação.','Agrupe condições e trate nulos para produzir um resultado previsível.','SELECT ID,NOME,COALESCE(ESTOQUE,0) AS ESTOQUE FROM PRODUTOS WHERE (ATIVO=1 AND PRECO>=80) OR CATEGORIA_ID IS NULL ORDER BY ID LIMIT 5','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda condições, nulos e paginação","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"SQLite — SQL","url":"https://sqlite.org/lang.html"}]'),
(179,'Extremos','Antes da batalha, entenda MIN e MAX.','MIN e MAX resumem os limites de uma coleção numérica.','SELECT MIN(PRECO) AS MENOR,MAX(PRECO) AS MAIOR FROM PRODUTOS WHERE ATIVO=1','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda MIN e MAX","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"SQLite — SQL","url":"https://sqlite.org/lang.html"}]'),
(180,'Resumo por categoria','Antes da batalha, entenda agregações por grupo.','Combine agregações para gerar indicadores por grupo.','SELECT CATEGORIA_ID,COUNT(*) AS PRODUTOS,ROUND(AVG(PRECO),2) AS MEDIA,MAX(PRECO) AS MAIOR FROM PRODUTOS WHERE ATIVO=1 GROUP BY CATEGORIA_ID ORDER BY CATEGORIA_ID','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda agregações por grupo","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"SQLite — SQL","url":"https://sqlite.org/lang.html"}]'),
(181,'Divisão protegida','Antes da batalha, entenda NULLIF.','NULLIF evita divisão por zero transformando o divisor inválido em NULL.','SELECT ID,TOTAL,ROUND(TOTAL/NULLIF(QUANTIDADE,0),2) AS UNITARIO FROM VENDAS ORDER BY ID','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda NULLIF","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"SQLite — SQL","url":"https://sqlite.org/lang.html"}]'),
(182,'Relações seguras','Antes da batalha, entenda JOIN, CASE e subconsulta.','Relacione entidades, trate ausências e compare com um indicador global.','SELECT P.NOME,COALESCE(C.NOME,''SEM CATEGORIA'') AS CATEGORIA,CASE WHEN P.PRECO>(SELECT AVG(PRECO) FROM PRODUTOS) THEN ''ACIMA'' ELSE ''PADRAO'' END AS FAIXA FROM PRODUTOS P LEFT JOIN CATEGORIAS C ON C.ID=P.CATEGORIA_ID ORDER BY P.ID','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda JOIN, CASE e subconsulta","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"SQLite — SQL","url":"https://sqlite.org/lang.html"}]'),
(183,'Ranking com janela','Antes da batalha, entenda RANK.','RANK atribui posições preservando empates.','SELECT NOME,PRECO,RANK() OVER (ORDER BY PRECO DESC) AS POSICAO FROM PRODUTOS ORDER BY POSICAO,NOME','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda RANK","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"SQLite — SQL","url":"https://sqlite.org/lang.html"}]'),
(184,'Análise por categoria','Antes da batalha, entenda CTE, JOIN e janela.','Uma CTE prepara os dados e a janela calcula rankings independentes.','WITH BASE AS (SELECT P.NOME,C.NOME AS CATEGORIA,P.PRECO FROM PRODUTOS P LEFT JOIN CATEGORIAS C ON C.ID=P.CATEGORIA_ID WHERE P.ATIVO=1) SELECT NOME,CATEGORIA,PRECO,RANK() OVER (PARTITION BY CATEGORIA ORDER BY PRECO DESC) AS POSICAO FROM BASE ORDER BY CATEGORIA,POSICAO','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda CTE, JOIN e janela","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"SQLite — SQL","url":"https://sqlite.org/lang.html"}]'),
(185,'Agregação condicional','Antes da batalha, entenda SUM com CASE.','CASE dentro de SUM conta subconjuntos sem consultas separadas.','SELECT COUNT(*) AS TOTAL,SUM(CASE WHEN ATIVO=1 THEN 1 ELSE 0 END) AS ATIVOS FROM PRODUTOS','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda SUM com CASE","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"SQLite — SQL","url":"https://sqlite.org/lang.html"}]'),
(186,'Registros sem relação','Antes da batalha, entenda NOT EXISTS.','NOT EXISTS encontra registros que não possuem correspondência.','SELECT P.ID,P.NOME FROM PRODUTOS P WHERE NOT EXISTS (SELECT 1 FROM VENDAS V WHERE V.PRODUTO_ID=P.ID) ORDER BY P.ID','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda NOT EXISTS","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"SQLite — SQL","url":"https://sqlite.org/lang.html"}]'),
(187,'Receita por categoria','Antes da batalha, entenda múltiplos JOINs e SUM.','Relatórios cruzam entidades antes de agregar seus indicadores.','SELECT C.NOME AS CATEGORIA,SUM(V.TOTAL) AS RECEITA FROM VENDAS V JOIN PRODUTOS P ON P.ID=V.PRODUTO_ID JOIN CATEGORIAS C ON C.ID=P.CATEGORIA_ID GROUP BY C.ID,C.NOME ORDER BY RECEITA DESC','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda múltiplos JOINs e SUM","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"SQLite — SQL","url":"https://sqlite.org/lang.html"}]'),
(188,'Percentual de receita','Antes da batalha, entenda agregação e janela.','Uma janela sobre agregações calcula participação no total.','SELECT PRODUTO_ID,SUM(TOTAL) AS RECEITA,ROUND(100.0*SUM(TOTAL)/SUM(SUM(TOTAL)) OVER (),2) AS PERCENTUAL FROM VENDAS GROUP BY PRODUTO_ID ORDER BY RECEITA DESC','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda agregação e janela","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"SQLite — SQL","url":"https://sqlite.org/lang.html"}]'),
(189,'Total acumulado','Antes da batalha, entenda SUM OVER ordenado.','A janela ordenada mantém as linhas enquanto acumula valores.','SELECT ID,DATA,TOTAL,SUM(TOTAL) OVER (ORDER BY DATA,ID) AS ACUMULADO FROM VENDAS ORDER BY DATA,ID','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda SUM OVER ordenado","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"SQLite — SQL","url":"https://sqlite.org/lang.html"}]'),
(190,'Comparação anterior','Antes da batalha, entenda LAG.','LAG acessa o valor da linha anterior sem autojunção.','SELECT ID,DATA,TOTAL,LAG(TOTAL) OVER (ORDER BY DATA,ID) AS ANTERIOR FROM VENDAS ORDER BY DATA,ID','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda LAG","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"SQLite — SQL","url":"https://sqlite.org/lang.html"}]'),
(191,'Top por categoria','Antes da batalha, entenda ROW_NUMBER particionado.','Numere dentro de cada categoria e filtre a primeira posição.','WITH RANKING AS (SELECT P.NOME,C.NOME AS CATEGORIA,P.PRECO,ROW_NUMBER() OVER (PARTITION BY C.ID ORDER BY P.PRECO DESC) AS POSICAO FROM PRODUTOS P JOIN CATEGORIAS C ON C.ID=P.CATEGORIA_ID WHERE P.ATIVO=1) SELECT NOME,CATEGORIA,PRECO FROM RANKING WHERE POSICAO=1 ORDER BY CATEGORIA','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda ROW_NUMBER particionado","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"SQLite — SQL","url":"https://sqlite.org/lang.html"}]'),
(192,'Dashboard profissional','Antes da batalha, entenda CTEs, agregações e JOINs.','Separe o cálculo em etapas nomeadas e entregue indicadores auditáveis.','WITH VENDAS_PRODUTO AS (SELECT PRODUTO_ID,SUM(QUANTIDADE) AS UNIDADES,SUM(TOTAL) AS RECEITA FROM VENDAS GROUP BY PRODUTO_ID), RANKING AS (SELECT PRODUTO_ID,UNIDADES,RECEITA,RANK() OVER (ORDER BY RECEITA DESC) AS POSICAO FROM VENDAS_PRODUTO) SELECT P.NOME,R.UNIDADES,R.RECEITA,R.POSICAO FROM RANKING R JOIN PRODUTOS P ON P.ID=R.PRODUTO_ID ORDER BY R.POSICAO,P.NOME','O exemplo ensina o conceito sem entregar a solução da batalha.','["Entenda CTEs, agregações e JOINs","Aplique o conceito no contexto pedido","Valide o resultado antes de atacar"]','["Ignorar a aula explicativa","Copiar sem adaptar ao objetivo"]','[{"label":"SQLite — SQL","url":"https://sqlite.org/lang.html"}]');
